namespace AtomUI.Controls.Data;

/// <summary>
/// Holds the display and editing attributes of one data member.
/// </summary>
/// <remarks>
/// <para>
/// For accessors generated by <see cref="GenerateDataMemberAccessorsAttribute" />, the values come from the
/// <c>Display</c>, <c>ReadOnly</c> and <c>Editable</c> attributes of the member. A hand-written
/// <see cref="DataMemberAccessor{TData, TValue}" /> receives them through its constructor.
/// </para>
/// </remarks>
public sealed class DataMemberAccessorMetadata
{
    /// <summary>
    /// The metadata of a member without display or editing attributes: every optional value is <see langword="null" />,
    /// the member is not read-only and it is editable.
    /// </summary>
    public static DataMemberAccessorMetadata Default { get; } = new();

    /// <summary>
    /// Gets the caption of the member, or <see langword="null" /> when the member does not specify one.
    /// </summary>
    /// <remarks>
    /// <para>
    /// A generated accessor takes it from the <c>ShortName</c>, or else the <c>Name</c>, of the member's
    /// <c>Display</c> attribute.
    /// </para>
    /// </remarks>
    public string? DisplayName { get; }

    /// <summary>
    /// Gets whether a control that generates fields or columns for the data type should include the member.
    /// <see langword="null" /> means that the member does not specify it.
    /// </summary>
    public bool? AutoGenerateField { get; }

    /// <summary>
    /// Gets the sort position of the member relative to the other members when fields or columns are generated.
    /// <see langword="null" /> means that the member does not specify a position.
    /// </summary>
    public int? Order { get; }

    /// <summary>
    /// Gets whether the member must not be edited by the user.
    /// </summary>
    /// <remarks>
    /// <para>
    /// This does not depend on whether the member has a setter: a member with a setter can still be read-only, and
    /// <see cref="IDataMemberAccessor.CanWrite" /> reports only that the setter exists. A generated accessor sets this
    /// property from a <c>ReadOnly</c> attribute with the value <see langword="true" /> on the member.
    /// </para>
    /// </remarks>
    public bool IsReadOnly { get; }

    /// <summary>
    /// Gets whether the user may edit the member. The default is <see langword="true" />. A generated accessor sets it
    /// to <see langword="false" /> for a member with an <c>Editable</c> attribute whose value is
    /// <see langword="false" />.
    /// </summary>
    public bool IsEditable { get; }

    /// <summary>
    /// Initializes the metadata with the attributes of one data member.
    /// </summary>
    /// <param name="displayName">
    /// The caption of the member, or <see langword="null" /> when it has none.
    /// </param>
    /// <param name="autoGenerateField">
    /// Whether a control that generates fields or columns should include the member, or
    /// <see langword="null" /> when the member does not specify it.
    /// </param>
    /// <param name="order">
    /// The sort position of the member among generated fields or columns, or <see langword="null" /> when the member
    /// does not specify one.
    /// </param>
    /// <param name="isReadOnly">
    /// Whether the member must not be edited by the user. The default is <see langword="false" />.
    /// </param>
    /// <param name="isEditable">
    /// Whether the user may edit the member. The default is <see langword="true" />.
    /// </param>
    public DataMemberAccessorMetadata(string? displayName = null,
                                      bool? autoGenerateField = null,
                                      int? order = null,
                                      bool isReadOnly = false,
                                      bool isEditable = true)
    {
        DisplayName       = displayName;
        AutoGenerateField = autoGenerateField;
        Order             = order;
        IsReadOnly        = isReadOnly;
        IsEditable        = isEditable;
    }
}

/// <summary>
/// Exposes the metadata of an accessor, which <see cref="IDataMemberAccessor" /> itself does not provide.
/// </summary>
/// <remarks>
/// <para>
/// <see cref="DataMemberAccessor{TData, TValue}" /> implements it. Cast an accessor to this interface to read the
/// metadata.
/// </para>
/// </remarks>
public interface IDataMemberAccessorMetadataProvider
{
    /// <summary>
    /// Gets the display and editing attributes of the member.
    /// </summary>
    DataMemberAccessorMetadata Metadata { get; }
}

/// <summary>
/// Exposes whether the data type of a descriptor is read-only, which <see cref="IDataMemberAccessorDescriptor" />
/// itself does not provide.
/// </summary>
/// <remarks>
/// <para>
/// <see cref="DataMemberAccessorDescriptor{TData}" /> implements it. Cast a descriptor to this interface to read
/// the flag.
/// </para>
/// </remarks>
public interface IDataMemberAccessorDescriptorMetadataProvider
{
    /// <summary>
    /// Gets whether the data type is marked read-only as a whole. A generated descriptor sets it from a
    /// <c>ReadOnly</c> attribute with the value <see langword="true" /> on the type.
    /// </summary>
    bool IsDataTypeReadOnly { get; }
}
